function render() {
  var i = idx(state);        // position of the current dial setting in G.snap
  var snap = G.snap[i];      // that setting's outcomes, read below by G.keys index
  document.querySelectorAll(".levels button").forEach(function (b) { b.setAttribute("aria-pressed", "false"); });
  var off = state[DI.pareto] === 0;
  rowEl[DI.avoidance_small].classList.toggle("is-off", off);
  // aria-disabled, not disabled: a disabled button gets no tap, so its tip could not open.
  // The click handler ignores the selection while the switch is off.
  rowEl[DI.avoidance_small].querySelectorAll("button").forEach(function (b) { b.setAttribute("aria-disabled", off ? "true" : "false"); });
  G.dials.forEach(function (dial, di) {
    var b = document.getElementById("dial-" + dial.key + "-" + state[di]);
    if (b) b.setAttribute("aria-pressed", "true");
  });
  var name = null;
  for (var k in namedIdx) if (namedIdx[k] === i) name = k;
  var ext = i === iMax ? "The highest total across all settings"
          : i === iMin ? "The lowest total across all settings" : null;
  document.getElementById("cell-name").textContent = "Main estimate\u00B9, " +
    (name ? (name === PREF ? "base scenario" : name + " scenario (Table 5)")
          : ext ? ext.toLowerCase() : "a setting the authors did not publish");
  document.getElementById("cell-value").textContent = fmtOut("$B", snap[K.main_estimate]);

  tbody.textContent = "";
  G.outcomes.forEach(function (label, oi) {
    var tr = document.createElement("tr");
    var th = document.createElement("th");
    th.setAttribute("scope", "row");
    th.textContent = label;
    tr.appendChild(th);
    var td = document.createElement("td");
    td.className = "cur";
    td.textContent = fmtOut(G.units[oi], snap[oi]);
    tr.appendChild(td);
    names.forEach(function (nm) {
      var td2 = document.createElement("td");
      if (nm === PREF) td2.className = "pref";
      td2.textContent = fmtOut(G.units[oi], G.snap[namedIdx[nm]][oi]);
      tr.appendChild(td2);
    });
    tbody.appendChild(tr);
  });
  drawBars(i);
}

